library ieee; 
use ieee.std_logic_1164.all; 
use ieee.std_logic_unsigned.all; 
entity a105 is 

port 

( 
clk,reset 

: in std_logic; --系統clk 及系統重置 


pa01,pa02,pb01,pb02 : in std_logic; --偵煙,感熱輸入 


clr 

: in std_logic; --狀態清除按鈕 


ro 


: out std_logic;--繼電器輸出 


soundo,led,pio : out std_logic--蜂鳴器及LED 燈號輸出及偵煙,感熱輸入信號合併輸出 

); 
end entity; 
architecture rtl of a105 is 

signal ff: std_logic_vector(24 downto 0); 

signal pi,sound,ros: std_logic; 

signal cn: std_logic_vector(3 downto 0); 

signal clrs: std_logic_vector(2 downto 0); 
begin 
pi<=not pa01 and pa02 and not pb01 and pb02; 
--偵煙,感熱輸入信號合併 
pio<=pi; 





--感熱輸入信號合併輸出 
led<=ff(22); 





--系統指示燈輸出 
soundo<=sound and ff(21); 



--蜂鳴器間歇警報聲輸出 
ro<=ros and ff(21); 




--繼電器信號輸出(電磁閥動作3 次) 

--除頻器 

process (clk, reset) --除頻器 

begin 


if (reset = '1') then 



ff <= (others=>'0'); 


elsif (rising_edge(clk)) then 
 ff <= ff+1; 


end if; 

end process; 


--火災信號監測及輸出信號輸出 

process (ff(19), reset) 

begin 


if (reset='1'or clrs(2)='1') then 



sound <= '0'; 
--蜂鳴器信號取消 



ros<='0'; 

--繼電器信號取消 



cn<="0000"; 
--計次計數器歸零 


elsif (rising_edge(ff(19))) then 



if pi='0' then 


--火災信號出現 




if cn<14 then 

--電磁閥動作3 次 





cn<=cn+1; 

--計次計數器+1 





if cn = 3 then 
--監測次數(防誤動作) 






ros<='1'; 
--啟動繼電器 






sound<='1'; 
--啟動蜂鳴器 





end if; 




else 





ros<='0'; 

--繼電器信號取消 




end if; 



else 




ros<='0'; 




if cn/=14 then 





cn<="0000"; 
--火災信號中斷取消計次 





sound<='0'; 

--重新偵測 




end if; 



end if; 


end if; 

end process; 


--按鈕防彈跳及雜訊 

process (ff(13)) 

begin 


if clr='0' then 



clrs<="000"; 


elsif (rising_edge(ff(13))) then 



clrs<=clrs+not clrs(2); 


end if; 

end process; 
end rtl;

偵煙感熱啟動電磁閥灑水系統主控器內部控制電路相當簡單，只是一個除頻器及監測火災信號電路而已，如下進一步說明: 
除頻器: 
由電源起始或重置按鈕信號(reset)按下為'1'時，將除頻器(ff)歸零: 






ff <= (others=>'0'); 
reset 消失後，由4MHz 石英晶體震盪器的正緣信號觸發，將使除頻器上數累進1 值: 
ff <= ff+1; 
除頻器進一步的運用，產生系統運作指示燈輸出控制信號: 
led<=ff(22); 
火災信號有1 動作型(感溫部分)及0 動作型(偵煙部分)，先整合起來(偵測兩組): 

火災信號監測及輸出信號輸出: 
由reset 及clr 按鈕確認信號clrs(2)可將輸出信號(警報器sound 及繼電器ros)及內部計次計數器(cn)清除: 
sound <= '0'; 







ros<='0'; 







cn<="0000"; 
以除頻器ff(19)間隔時段監測火警信號(pi='0')，如有發現時，則計次監測: 
cn<=cn+1; 
如持續測得四次時，即啟動輸出信號： 







ros<='1'; 
sound <= '1'; 
此時蜂鳴器會發出間歇警報聲： 
soundo<=sound and ff(21); 
繼電器也有相同的動作： 
ro<=ros and ff(21); 
繼電器控制的是電磁閥，所以電磁閥就會動作了，在計次計數器(cn)達14 次時，將關閉繼電器輸出: 
pi<=not pa01 and pa02 and not pb01 and pb02; 

繼電器ros<='0'; 
而計次計數器(cn)達14 次前時，繼電器將會動作3 次控制電磁閥動作，電磁閥每一次的激磁瞬間動作力是最大的，如此可防止電磁閥久未動作，及管內液體可能含有泡沫沉澱物而卡住不動作或動作不確實，3 次控制電磁閥動作，可排除此現象；電磁閥動作後，將會由機構將電磁閥的活動鐵心卡住，如圖14 所示，電磁閥動作後，及時不激磁時，管路仍保持暢通，一齊開放閥的閥門洩壓後而打開，開放灑水頭噴出泡沫水，達到滅火作用；因電磁閥管路已持續打開，所以就不用再激磁，可節省電力外，也能在因火災關係將控制系統破壞時，仍可持續滅火不中斷。 

圖14 電磁閥自保持機構設計圖 
如電磁閥已動作後，會繼續保持動作(已不通電了)，而蜂鳴器會持續作響，等火災過後，必需由人工按下clr 按紐才能解除警報聲，而電磁閥自保持部分也是需由人工解除。 
如計次計數器(cn)未達14 次前時，火災信號消失時(pi='1')，將輸出全部取消、計次計數器歸零: 
ros<='0'; 







cn<="0000"; 







sound<='0'; 
如此當有再感測到火災信號時，可再重新檢測。 
如計次計數器(cn)已達14 次時，火災信號消失時(pi='1')，則保持蜂鳴器作響、計次計數器維持不變，所以如再有火災信號時，不再有任何變化(電磁閥已自保持、蜂鳴器仍繼續作響)。 
解除輸出是由clr 按鈕按下來啟動，為求穩定不受干擾，所以經防彈跳及防雜訊處理。
